<template>
  <F7Page
    name="reactive-demo"
    infinite
    :infinite-distance="250"
    @infinite="handleProductsInfinite"
    @page:afterin="bindPageScroll"
    @page:beforeout="unbindPageScroll"
    @page:beforeunmount="unbindPageScroll"
  >
    <MetricsDevTools />

    <F7Navbar title="Reactive Products" large transparent back-link="Back">
      <F7NavRight>
        <F7Link @click="isLogsPopupOpen = true">
          <ILucideListTree class="h-5 w-5" />
          <span class="if-not-md ml-1">Logs</span>
        </F7Link>
        <F7Link @click="toggleDevTools()">
          <ILucideBarChart2 class="h-5 w-5" />
          <span class="if-not-md ml-1">Metrics</span>
        </F7Link>
      </F7NavRight>
      <F7Searchbar
        class="reactive-products-searchbar"
        expandable
        custom-search
        placeholder="Search products"
        :value="productSearchQuery"
        @focus="prepareProductSearch"
        @searchbar:enable="prepareProductSearch"
        @searchbar:search="handleProductSearch"
        @searchbar:clear="clearProductSearch"
        @searchbar:disable="handleProductSearchDisable"
      />
    </F7Navbar>

    <F7Block strong inset class="rounded-panel shadow-sm">
      <div class="grid grid-cols-3 gap-3 text-center">
        <div>
          <div class="stat-value">{{ totalProducts }}</div>
          <div class="stat-label">Products</div>
        </div>
        <div>
          <div class="stat-value text-green-500">{{ saleableProducts }}</div>
          <div class="stat-label">Sale OK</div>
        </div>
        <div>
          <div class="stat-value text-orange-500">
            {{ competitorProducts }}
          </div>
          <div class="stat-label">Competitor</div>
        </div>
      </div>
    </F7Block>

    <F7List strong inset dividers class="rounded-panel overflow-hidden shadow-sm">
      <F7ListInput
        v-model:value="newProductName"
        placeholder="Demo product name"
        type="text"
        @keyup.enter="handleAddProduct"
      >
        <template #media>
          <ILucidePackagePlus class="text-blue-500" />
        </template>
      </F7ListInput>

      <F7ListInput
        v-model:value="newProductPrice"
        placeholder="List price"
        type="number"
        min="0"
        step="0.01"
        @keyup.enter="handleAddProduct"
      >
        <template #media>
          <ILucideBadgeDollarSign class="text-green-500" />
        </template>
      </F7ListInput>

      <F7ListItem title="Type" smart-select :smart-select-params="{ openIn: 'popover' }">
        <template #media>
          <ILucideBoxes class="text-purple-500" />
        </template>
        <select v-model="newProductType">
          <option value="product">Stockable</option>
          <option value="consu">Consumable</option>
          <option value="service">Service</option>
        </select>
      </F7ListItem>

      <F7ListItem title="Sale enabled">
        <template #media>
          <ILucideShoppingCart class="text-green-500" />
        </template>
        <template #after>
          <F7Toggle v-model:checked="newProductSaleOk" />
        </template>
      </F7ListItem>

      <F7ListItem title="Competitor product">
        <template #media>
          <ILucideSwords class="text-orange-500" />
        </template>
        <template #after>
          <F7Toggle v-model:checked="newProductCompetitor" />
        </template>
      </F7ListItem>

      <F7Block class="m-0 p-4 pt-0">
        <div class="grid grid-cols-2 gap-3">
          <F7Button
            fill
            round
            large
            @click="handleAddProduct"
            :disabled="!newProductName.trim() || isAdding"
          >
            Add Product
          </F7Button>
          <F7Button tonal round large @click="injectRawProduct"> Raw Insert </F7Button>
        </div>
      </F7Block>
    </F7List>

    <F7BlockTitle>
      Products
      <span class="text-xs font-normal text-gray-400">
        loaded {{ visibleProductCount }} of {{ totalProducts }}
      </span>
    </F7BlockTitle>
    <F7List
      v-show="showProductSearchEmptyState"
      v-if="products && products.length > 0"
      strong
      inset
      dividers
      class="rounded-panel overflow-hidden shadow-sm"
    >
      <F7ListItem title="Nothing found" />
    </F7List>
    <div v-if="loading && !products" class="p-8 text-center">
      <F7Preloader />
      <p class="mt-2 text-gray-400">Reading local SQLite...</p>
    </div>

    <F7List
      v-else-if="products && products.length > 0"
      strong
      inset
      dividers
      media-list
      virtual-list
      :virtual-list-params="virtualListParams"
      class="reactive-products-list rounded-panel overflow-hidden shadow-sm"
    >
      <ul>
        <F7ListItem
          v-for="(product, index) in virtualListData.items"
          :key="product.id"
          class="product-virtual-item"
          media-item
          swipeout
          link="#"
          :subtitle="productSubtitle(product)"
          :style="`top: ${virtualListData.topPosition}px`"
          :virtual-list-index="virtualListData.fromIndex + index"
          @click="openProductDetails(product)"
        >
          <template #media>
            <div class="product-mark">
              {{ product.name.slice(0, 1).toUpperCase() }}
            </div>
          </template>

          <template #title>
            <div class="flex min-w-0 items-center gap-2">
              <span class="truncate">{{ product.name }}</span>
              <F7Badge v-if="product.syncStatus !== 'synced'" color="orange">
                {{ product.syncStatus }}
              </F7Badge>
            </div>
          </template>

          <template #after>
            <div class="text-right">
              <div class="font-semibold">{{ formatPrice(product.listPrice) }}</div>
              <div class="mt-1 flex justify-end gap-1">
                <F7Badge v-if="product.saleOk" color="green">Sale</F7Badge>
                <F7Badge v-if="product.competitor" color="orange">Rival</F7Badge>
              </div>
            </div>
          </template>

          <F7SwipeoutActions right>
            <F7SwipeoutButton color="green" @click="toggleSale(product.id)">
              <ILucideShoppingCart class="h-5 w-5" />
            </F7SwipeoutButton>
            <F7SwipeoutButton color="orange" @click="toggleCompetitor(product.id)">
              <ILucideSwords class="h-5 w-5" />
            </F7SwipeoutButton>
          </F7SwipeoutActions>
        </F7ListItem>
      </ul>
    </F7List>

    <F7Block
      v-if="products && products.length > 0 && hasMoreProducts"
      class="pb-2 pt-0 text-center text-xs text-gray-400"
    >
      <F7Preloader v-if="isLoadingMore" class="mr-2" />
      <span>{{ isLoadingMore ? "Loading more products..." : "Scroll for more" }}</span>
    </F7Block>

    <F7Block v-else strong inset class="rounded-panel p-8 text-center">
      <ILucidePackageSearch class="mx-auto mb-2 h-12 w-12 text-gray-300" />
      <p class="text-gray-400">No products found locally. Add a demo product or run sync.</p>
    </F7Block>

    <F7Fab v-if="showScrollTopFab" position="right-bottom" color="blue" @click="openProductSearch">
      <ILucideSearch class="h-5 w-5" />
    </F7Fab>

    <F7Sheet
      v-model:opened="isProductSheetOpen"
      class="product-details-sheet"
      style="height: auto; --f7-sheet-bg-color: #fff"
      swipe-to-close
      backdrop
    >
      <F7BlockTitle large>Edit Product</F7BlockTitle>
      <F7List strong inset dividers class="mb-4">
        <F7ListInput label="Name" v-model:value="editingProduct.name" placeholder="Product name" />
        <F7ListInput
          label="List price"
          v-model:value="editingProduct.price"
          type="number"
          min="0"
          step="0.01"
        />
        <F7ListItem title="Sale enabled">
          <template #after>
            <F7Toggle v-model:checked="editingProduct.saleOk" />
          </template>
        </F7ListItem>
        <F7ListItem title="Competitor product">
          <template #after>
            <F7Toggle v-model:checked="editingProduct.competitor" />
          </template>
        </F7ListItem>
      </F7List>

      <F7Block class="space-y-3!">
        <F7Button large fill round @click="saveProductDetails"> Save Changes </F7Button>
        <F7Button large tonal round color="green" class="mt-2" @click="toggleSaleFromSheet">
          Toggle Sale Flag
        </F7Button>
        <F7Button large tonal round color="orange" class="mt-2" @click="toggleCompetitorFromSheet">
          Toggle Competitor Flag
        </F7Button>
      </F7Block>
    </F7Sheet>

    <F7Popup
      v-model:opened="isLogsPopupOpen"
      class="reactive-logs-popup"
      swipe-to-close="to-bottom"
      push
    >
      <F7Page>
        <F7Navbar title="Reactivity Logs">
          <F7NavRight>
            <F7Link popup-close>Close</F7Link>
          </F7NavRight>
        </F7Navbar>

        <F7Block strong inset class="rounded-panel shadow-sm">
          <div class="grid grid-cols-2 gap-3">
            <F7Button tonal color="red" @click="logStore.clearLogs">
              <ILucideTrash2 class="mr-1 h-4 w-4" />
              Clear
            </F7Button>
            <F7Button tonal @click="refetch">
              <ILucideRefreshCw class="mr-1 h-4 w-4" />
              Refetch
            </F7Button>
          </div>
        </F7Block>

        <F7Block id="logs-container" strong inset class="logs-viewport rounded-panel shadow-sm">
          <div v-if="logStore.logs.length === 0" class="py-4 text-center italic text-gray-400">
            Interaction logs will appear here...
          </div>
          <div
            v-for="log in logStore.logs"
            :key="log.id"
            class="log-entry"
            :class="'log-' + log.type"
          >
            <span class="log-time">{{ log.time }}</span>
            <span class="log-type">[{{ log.type.toUpperCase() }}]</span>
            <span class="log-msg">{{ log.message }}</span>
          </div>
        </F7Block>
      </F7Page>
    </F7Popup>
  </F7Page>
</template>

<script setup lang="ts">
import { f7 } from "framework7-vue";
import type { ProductDemoItem } from "../composables/useReactiveProducts";
import { useReactiveProducts } from "../composables/useReactiveProducts";

const { toggleDevTools } = useQueryMetrics();
const logStore = useLogStore();

const {
  products,
  totalProducts,
  saleableProducts,
  competitorProducts,
  visibleProductCount,
  hasMoreProducts,
  loading,
  isLoadingMore,
  isAdding,
  addProduct,
  toggleSale,
  toggleCompetitor,
  renameProduct,
  injectRawProduct,
  loadMoreProducts,
  loadAllProducts,
  refetch,
} = useReactiveProducts();

const newProductName = ref("");
const newProductPrice = ref("10");
const newProductType = ref<"consu" | "service" | "product">("product");
const newProductSaleOk = ref(true);
const newProductCompetitor = ref(false);

const isProductSheetOpen = ref(false);
const isLogsPopupOpen = ref(false);
const showScrollTopFab = ref(false);
const isProductSearchActive = ref(false);
const productSearchQuery = ref("");
const productSearchMatchedCount = ref(0);
const virtualListInstance = shallowRef<any>(null);
const pageContentEl = shallowRef<HTMLElement | null>(null);
const virtualListData = ref<{
  items: ProductDemoItem[];
  topPosition: number;
  fromIndex: number;
  toIndex: number;
}>({
  items: [],
  topPosition: 0,
  fromIndex: 0,
  toIndex: 0,
});
const editingProduct = ref({
  id: 0,
  name: "",
  price: "0",
  saleOk: false,
  competitor: false,
});
const showProductSearchEmptyState = computed(
  () => productSearchQuery.value.trim().length > 0 && productSearchMatchedCount.value === 0,
);

function formatPrice(price: number) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 2,
  }).format(price);
}

function productSubtitle(product: ProductDemoItem) {
  return [product.defaultCode, product.brandName, product.categoryName, product.uomName]
    .filter(Boolean)
    .join(" · ");
}

function renderVirtualList(vl: any, data: any) {
  virtualListInstance.value = vl;
  virtualListData.value = {
    items: data.items ?? [],
    topPosition: data.topPosition ?? 0,
    fromIndex: data.fromIndex ?? 0,
    toIndex: data.toIndex ?? 0,
  };

  if (virtualListData.value.toIndex >= visibleProductCount.value - 20) {
    void loadMoreProducts();
  }
}

function searchAllProducts(query: string, items: ProductDemoItem[]) {
  const normalizedQuery = query.trim().toLowerCase();
  if (!normalizedQuery) return items.map((_, index) => index);

  const found: number[] = [];
  for (let index = 0; index < items.length; index += 1) {
    const product = items[index];
    if (!product) continue;

    const searchable = [
      product.name,
      product.defaultCode,
      product.brandName,
      product.categoryName,
      product.uomName,
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    if (searchable.includes(normalizedQuery)) found.push(index);
  }

  return found;
}

async function handleProductsInfinite() {
  if (!hasMoreProducts.value || isLoadingMore.value) return;
  await loadMoreProducts();
}

const virtualListParams = computed(() => ({
  items: products.value ?? [],
  searchAll: searchAllProducts,
  renderExternal: renderVirtualList,
  height: 96,
  rowsBefore: 18,
  rowsAfter: 18,
}));

watch(
  products,
  (nextProducts) => {
    if (!virtualListInstance.value) return;
    virtualListInstance.value.replaceAllItems(nextProducts ?? []);
    applyVirtualProductSearch(productSearchQuery.value, false);
  },
  { flush: "post" },
);

function handlePageScroll() {
  const pageContent = pageContentEl.value;
  const shouldShowScrollTools = (pageContent?.scrollTop ?? 0) >= (pageContent?.clientHeight ?? 0);

  if (isProductSearchActive.value) {
    showScrollTopFab.value = true;
    return;
  }

  if (showScrollTopFab.value === shouldShowScrollTools) return;

  showScrollTopFab.value = shouldShowScrollTools;
  if (!shouldShowScrollTools) {
    f7.searchbar.disable(".reactive-products-searchbar");
    clearProductSearch();
  }
}

function bindPageScroll() {
  const nextPageContentEl = document.querySelector<HTMLElement>(
    '.page[data-name="reactive-demo"] .page-content',
  );
  if (pageContentEl.value === nextPageContentEl) return;

  unbindPageScroll();
  pageContentEl.value = nextPageContentEl;
  pageContentEl.value?.addEventListener("scroll", handlePageScroll, {
    passive: true,
  });
  handlePageScroll();
}

function unbindPageScroll() {
  pageContentEl.value?.removeEventListener("scroll", handlePageScroll);
  pageContentEl.value = null;
  showScrollTopFab.value = false;
}

async function openProductSearch() {
  isProductSearchActive.value = true;
  showScrollTopFab.value = true;
  await prepareProductSearch();
  f7.searchbar.enable(".reactive-products-searchbar");
}

async function prepareProductSearch() {
  await loadAllProducts();
  applyVirtualProductSearch(productSearchQuery.value, false);
}

function applyVirtualProductSearch(query: string, resetScrollTop = true) {
  const virtualList = virtualListInstance.value;
  if (!virtualList) return;

  if (!query.trim()) {
    productSearchMatchedCount.value = virtualList.items?.length ?? 0;
    virtualList.resetFilter();
    return;
  }

  const matches = searchAllProducts(query, virtualList.items ?? []);
  productSearchMatchedCount.value = matches.length;
  virtualList.filterItems(matches, resetScrollTop);
}

async function handleProductSearch(...args: unknown[]) {
  const query = String(args[1] ?? "");
  isProductSearchActive.value = true;
  productSearchQuery.value = query;

  if (query.trim()) {
    await loadAllProducts();
  }

  applyVirtualProductSearch(query, false);
}

function clearProductSearch() {
  productSearchQuery.value = "";
  productSearchMatchedCount.value = virtualListInstance.value?.items?.length ?? 0;
  virtualListInstance.value?.resetFilter();
}

function handleProductSearchDisable() {
  isProductSearchActive.value = false;
  clearProductSearch();
  const pageContent = pageContentEl.value;
  showScrollTopFab.value = (pageContent?.scrollTop ?? 0) >= (pageContent?.clientHeight ?? 0);
}

function openProductDetails(product: ProductDemoItem) {
  editingProduct.value = {
    id: product.id,
    name: product.name,
    price: String(product.listPrice),
    saleOk: product.saleOk,
    competitor: product.competitor,
  };
  isProductSheetOpen.value = true;
}

async function handleAddProduct() {
  const name = newProductName.value.trim();
  if (!name) return;

  await addProduct({
    name,
    price: Number(newProductPrice.value || 0),
    type: newProductType.value,
    saleOk: newProductSaleOk.value,
    competitor: newProductCompetitor.value,
  });

  newProductName.value = "";
  newProductPrice.value = "10";
  newProductType.value = "product";
  newProductSaleOk.value = true;
  newProductCompetitor.value = false;
}

async function saveProductDetails() {
  if (!editingProduct.value.name.trim()) return;

  await renameProduct({
    id: editingProduct.value.id,
    name: editingProduct.value.name.trim(),
    price: Number(editingProduct.value.price || 0),
  });

  const product = products.value?.find((item) => item.id === editingProduct.value.id);

  if (product && product.saleOk !== editingProduct.value.saleOk) {
    await toggleSale(editingProduct.value.id);
  }

  if (product && product.competitor !== editingProduct.value.competitor) {
    await toggleCompetitor(editingProduct.value.id);
  }

  isProductSheetOpen.value = false;
}

async function toggleSaleFromSheet() {
  await toggleSale(editingProduct.value.id);
  editingProduct.value.saleOk = !editingProduct.value.saleOk;
}

async function toggleCompetitorFromSheet() {
  await toggleCompetitor(editingProduct.value.id);
  editingProduct.value.competitor = !editingProduct.value.competitor;
}

watch(
  () => logStore.logs.length,
  () => {
    nextTick(() => {
      const container = document.getElementById("logs-container");
      if (container) container.scrollTop = 0;
    });
  },
);
</script>

