<template>
  <F7Page name="catalog-tracer">
    <F7Navbar title="Catalog Tracer" back-link="Back" />

    <F7Block strong inset class="rounded-panel shadow-sm">
      <div class="grid grid-cols-2 gap-3 text-center">
        <div>
          <div class="stat-value">{{ products.length }}</div>
          <div class="stat-label">Products</div>
        </div>
        <div>
          <div class="stat-value text-green-500">{{ activeCount }}</div>
          <div class="stat-label">Active</div>
        </div>
      </div>
      <p class="mt-3 text-center text-xs text-gray-400">
        createRepository → reactiveRepo → useReactiveQuery → F7. Toggling a row writes through rdb
        and repaints with no manual refresh.
      </p>
    </F7Block>

    <div v-if="loading && products.length === 0" class="p-8 text-center">
      <F7Preloader />
      <p class="mt-2 text-gray-400">Reading local SQLite...</p>
    </div>

    <F7List
      v-else-if="products.length > 0"
      strong
      inset
      dividers
      media-list
      class="rounded-panel overflow-hidden shadow-sm"
    >
      <F7ListItem
        v-for="product in products"
        :key="product.id"
        :title="product.name"
        :subtitle="product.default_code ?? '—'"
      >
        <template #after>
          <F7Badge :color="isActive(product) ? 'green' : 'gray'" class="mr-2">
            {{ isActive(product) ? "active" : "inactive" }}
          </F7Badge>
          <F7Button small tonal :disabled="pending" @click="toggleActive(product)">
            Toggle
          </F7Button>
        </template>
      </F7ListItem>
    </F7List>

    <F7Block v-else strong inset class="rounded-panel p-8 text-center">
      <p class="text-gray-400">No products in local SQLite. Run sync, then reopen this page.</p>
    </F7Block>

    <F7Block v-if="error" class="text-center text-sm text-red-500">
      {{ error.message }}
    </F7Block>
  </F7Page>
</template>

<script setup lang="ts">
import { computed } from "vue";
import { reactiveRepo } from "@/shared/composables/reactiveRepo";
import { productRepo } from "@/domains/product";
import type { Row } from "@/shared/database/repository";

const catalog = reactiveRepo(productRepo);

const {
  data: products,
  loading,
  error,
} = catalog.useList({
  orderBy: { column: "name", direction: "asc" },
});

const { execute: updateProduct, pending } = catalog.useMutation("update");

const activeCount = computed(() => products.value.filter((product) => isActive(product)).length);

function isActive(product: Row<"product_product">): boolean {
  return Boolean(product.active);
}

async function toggleActive(product: Row<"product_product">): Promise<void> {
  await updateProduct(product.id, { active: !isActive(product) });
}
</script>

<style scoped>
.rounded-panel {
  border-radius: 1.25rem !important;
}

.stat-value {
  font-size: 1.875rem;
  line-height: 2.25rem;
  font-weight: 700;
}

.stat-label {
  font-size: 0.6875rem;
  color: #9ca3af;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
</style>
